package br.com.confirmacao.professional.application;import br.com.confirmacao.professional.domain.Professional;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.user.infrastructure.UserRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.UUID;
@Service public class ProfessionalService{private final ProfessionalRepository repo;private final UserRepository users;public ProfessionalService(ProfessionalRepository r,UserRepository u){repo=r;users=u;}@Transactional public Professional create(String n,String e,String p,String reg){if(repo.existsByEmailIgnoreCase(e))throw new ProfessionalAlreadyExistsException("Já existe um profissional com este e-mail");if(reg!=null&&!reg.isBlank()&&repo.existsByRegistrationNumber(reg))throw new ProfessionalAlreadyExistsException("Já existe um profissional com este registro");return repo.save(new Professional(n,e,p,reg));}@Transactional(readOnly=true)public Page<Professional> findAll(Pageable p){return repo.findAll(p);}@Transactional(readOnly=true)public Professional findById(UUID id){return repo.findById(id).orElseThrow(()->new ProfessionalNotFoundException(id));}@Transactional public Professional update(UUID id,String n,String e,String p,String reg){Professional x=findById(id);if(repo.existsByEmailIgnoreCaseAndIdNot(e,id))throw new ProfessionalAlreadyExistsException("Já existe um profissional com este e-mail");if(reg!=null&&!reg.isBlank()&&repo.existsByRegistrationNumberAndIdNot(reg,id))throw new ProfessionalAlreadyExistsException("Já existe um profissional com este registro");var user=users.findByProfessionalId(id).orElseThrow(()->new IllegalStateException("Profissional sem usuário de acesso"));if(users.existsByEmailIgnoreCaseAndIdNot(e,user.getId()))throw new ProfessionalAlreadyExistsException("Já existe um usuário com este e-mail");x.update(n,e,p,reg);user.updateIdentity(n,e);return x;}@Transactional public void activate(UUID id){var professional=findById(id);var user=users.findByProfessionalId(id).orElseThrow(()->new IllegalStateException("Profissional sem usuário de acesso"));professional.activate();user.activate();}@Transactional public void deactivate(UUID id){var professional=findById(id);var user=users.findByProfessionalId(id).orElseThrow(()->new IllegalStateException("Profissional sem usuário de acesso"));professional.deactivate();user.deactivate();}}
